def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "play_loud_audio": And([
            Not(self.customer_present),
            self.robot_has(self.promotional_audio),
            self.setting_is_shopping_mall,
            Not(self.robot_has_volume_control)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
